Algorithm KioscoImperativo
  Define total As Integer <- 0;
  total <- total + 3 * 3;
  total <- total + 5 * 2;
  Write "Total: ", total;
  total <- total - total Div 10;
  Write "Con descuento: ", total;
EndAlgorithm

Class Caja
  Private Define total As Integer;

  Method Constructor()
    This.total <- 0;
  EndMethod

  Method Vender(precio As Integer, cantidad As Integer)
    This.total <- This.total + precio * cantidad;
  EndMethod

  Method Total() As Integer
    Return This.total;
  EndMethod

  Method ConDescuento() As Integer
    Return This.total - This.total Div 10;
  EndMethod
EndClass

Algorithm KioscoObjetos
  Define caja As Caja <- New Caja();
  caja.Vender(3, 3);
  caja.Vender(5, 2);
  Write "Total: ", caja.Total();
  Write "Con descuento: ", caja.ConDescuento();
EndAlgorithm

Function importe <- Linea(precio As Integer, cantidad As Integer)
  Define importe As Integer;
  importe <- precio * cantidad;
EndFunction

Function monto <- ConDescuento(total As Integer)
  Define monto As Integer;
  monto <- total - total Div 10;
EndFunction

Algorithm KioscoFuncional
  Define total As Integer <- Linea(3, 3) + Linea(5, 2);
  Write "Total: ", total;
  Write "Con descuento: ", ConDescuento(total);
EndAlgorithm
